import type { CSSProperties } from 'react'
import manifest from '../data/image-sizes.json'

type Entry = { w: number; h: number; sizes: number[] }
const SIZES = manifest as Record<string, Entry>

interface Props {
  src: string
  alt: string
  /** The `sizes` attribute: how wide the image renders. */
  sizes?: string
  className?: string
  style?: CSSProperties
  priority?: boolean
}

/** Responsive <img> for files in /public/images, using sizes generated by `npm run images`. */
export function Img({ src, alt, sizes = '100vw', className = '', style, priority }: Props) {
  const name = src.split('/').pop()!.replace(/\.webp$/, '')
  const entry = SIZES[name]
  const srcSet = entry
    ? [...entry.sizes.map((w) => `/images/r/${name}-${w}.webp ${w}w`), `${src} ${entry.w}w`].join(', ')
    : undefined
  return (
    <img
      src={src}
      srcSet={srcSet}
      sizes={srcSet ? sizes : undefined}
      width={entry?.w}
      height={entry?.h}
      alt={alt}
      loading={priority ? 'eager' : 'lazy'}
      fetchPriority={priority ? 'high' : 'auto'}
      decoding="async"
      className={className}
      style={style}
      draggable={false}
    />
  )
}
